dir.create('figures',showWarnings=FALSE)
a<-read.csv('../data/author_results.csv');s<-a[a$spec=='AF1',];terms<-c(paste0('pre_',6:2),'current',paste0('post_',1:4));s<-s[match(terms,s$term),];x<-c(-6:-2,0:4);z<-qt(.95,257)
png('figures/author_event.png',width=1400,height=700,res=170)
plot(x,s$b,type='b',pch=16,ylim=range(c(s$b-z*s$se,s$b+z*s$se)),xlab='Event time (endpoints binned)',ylab='Economic security index',main='Author event dummies: 90% CI',xaxt='n');axis(1,at=-6:4);arrows(x,s$b-z*s$se,x,s$b+z*s$se,angle=90,code=3,length=.04);abline(h=0,col='gray');abline(v=-.5,lty=2,col='gray');points(-1,0,pch=16,col='gray');dev.off()
p<-read.csv('../data/placebo.csv');png('figures/placebo.png',width=1600,height=650,res=170);par(mfrow=c(1,2));plot(p$b,p$p,pch=16,cex=.4,xlab='Placebo coefficient',ylab='Original-code P value',main='500 draws; separate seed 12345');abline(h=.1,lty=2,col='gray');plot(density(p$b),xlab='Placebo coefficient',main='Placebo density');abline(v=a$b[a$spec=='B2'],col='red',lwd=2);legend('topright',legend='Author baseline',col='red',lty=1,bty='n',cex=.8);dev.off()
d<-read.csv('../data/modern_results_long.csv',fileEncoding='UTF-8-BOM');q<-d[d$spec=='B2',];q<-q[match(c('twfe','csa','bjs'),q$method),];png('figures/baseline_comparison.png',width=1350,height=650,res=170);par(mar=c(4,13,3,1));plot(q$b_raw,1:3,xlim=range(c(q$b_raw-1.96*q$se_raw,q$b_raw+1.96*q$se_raw)),yaxt='n',ylab='',xlab='Original outcome units; 95% normal CI',pch=16,main='Controlled baseline: author sample');axis(2,at=1:3,labels=c('TWFE','CSA (unbalanced)','BJS'),las=1);arrows(q$b_raw-1.96*q$se_raw,1:3,q$b_raw+1.96*q$se_raw,1:3,angle=90,code=3,length=.05);abline(v=0,lty=2,col='gray');dev.off()
